typedef unsigned long long big_int;

class stringx;

class string_buf
{
  friend class stringx;
  friend inline bool operator==(const stringx &, const stringx &);

  big_int *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;

public:
  inline bool is_equal(const string_buf &buf) const
  {
    if (buf.block_length != block_length) return false;
    for (int i = 0; i < block_length; i++)
      if (!(buf.data[i] == data[i])) return false;
    return true;
  }
};

class stringx
{
  friend inline bool operator==(const stringx &, const stringx &);

  char *chars;
  string_buf *my_buf;

public:
  stringx();
  stringx(const char *str, int len = -1);
  ~stringx();

  inline const char *c_str() const
  {
    return chars;
  }

  inline int size() const
  {
    return my_buf->char_length;
  }
};

inline bool operator==(const stringx &lhs, const stringx &rhs)
{
  return lhs.my_buf->is_equal(*rhs.my_buf);
}

inline bool operator!=(const stringx &lhs, const stringx &rhs)
{
  return !(lhs == rhs);
}

class os_file
{
public:
  enum mode_flags
  {
    FILE_READ = 1
  };

  ~os_file();

private:
  char data[64];
};

class text_file
{
public:
  ~text_file();

private:
  char data[64];
};

class chunk_file
{
public:
  enum chunk_file_flags_t
  {
    FILE_TEXT = 0x0100
  };

  chunk_file();
  void open(const stringx &name, int flags = os_file::FILE_READ);
  void close();

private:
  int type;
  int padding;
  os_file binary;
  text_file text;
  char remainder[152];
};

void serial_in(chunk_file &io, stringx *d);
bool file_finder_exists(const stringx &filename, const stringx &extension,
                        stringx *found_name = 0);
void error(const char *fmt, ...);
extern const stringx chunkend_label;

class ai_interface
{
  void read_goal(chunk_file &fs, const stringx &label);

public:
  void read_goal_pack(const stringx &file);
};

void ai_interface::read_goal_pack(const stringx &file)
{
  stringx       filename;

  if (!file_finder_exists(file, stringx(".gpk"), &filename) )
  {
    error("File '%s' not found!", file.c_str());
    return;
  }

	chunk_file    fs;
  fs.open( filename, os_file::FILE_READ | chunk_file::FILE_TEXT );

  stringx label;
  for ( serial_in(fs,&label); label!=chunkend_label && label.size() > 0; serial_in(fs,&label) )
    read_goal(fs, label);

  fs.close();
}
